'use client'

import { useState, useEffect } from 'react'
import { Activity, RefreshCw, Unplug, CheckCircle2, AlertCircle } from 'lucide-react'
import { SamsungHealthService, getSamsungHealthToken, storeSamsungHealthToken, removeSamsungHealthToken } from '@/lib/samsungHealth'

interface SamsungHealthConnectProps {
  userId: string
  onSync: (sessions: any[]) => void
}

export function SamsungHealthConnect({ userId, onSync }: SamsungHealthConnectProps) {
  const [isConnected, setIsConnected] = useState(false)
  const [isSyncing, setIsSyncing] = useState(false)
  const [lastSync, setLastSync] = useState<Date | null>(null)
  const [syncStatus, setSyncStatus] = useState<'idle' | 'success' | 'error'>('idle')

  useEffect(() => {
    // Check if Samsung Health is already connected
    const token = getSamsungHealthToken(userId)
    setIsConnected(!!token)

    // Load last sync time
    const lastSyncStr = localStorage.getItem(`samsung_health_last_sync_${userId}`)
    if (lastSyncStr) {
      setLastSync(new Date(lastSyncStr))
    }
  }, [userId])

  const handleConnect = async () => {
    // In a real implementation, this would redirect to Samsung Health OAuth
    // For now, we'll use a placeholder flow
    
    const confirmed = confirm(
      'Samsung Health Integration Setup:\n\n' +
      '1. You need to register your app at https://developer.samsung.com/health\n' +
      '2. Get your Client ID and Client Secret\n' +
      '3. Configure OAuth redirect URI\n' +
      '4. Add credentials to your .env.local\n\n' +
      'This is a placeholder - would you like to continue with mock data for testing?'
    )

    if (confirmed) {
      // Mock token for testing
      const mockToken = 'mock_samsung_health_token_' + Date.now()
      storeSamsungHealthToken(userId, mockToken)
      setIsConnected(true)
      setSyncStatus('success')
      setTimeout(() => setSyncStatus('idle'), 3000)
    }
  }

  const handleDisconnect = () => {
    if (confirm('Disconnect Samsung Health? Your health data will no longer sync.')) {
      removeSamsungHealthToken(userId)
      setIsConnected(false)
      setLastSync(null)
    }
  }

  const handleSync = async () => {
    setIsSyncing(true)
    setSyncStatus('idle')

    try {
      const token = getSamsungHealthToken(userId)
      if (!token) {
        throw new Error('Not connected')
      }

      const service = new SamsungHealthService(token)

      // Fetch last 7 days of data
      const endDate = new Date()
      const startDate = new Date()
      startDate.setDate(startDate.getDate() - 7)

      const [sleepData, workoutData] = await Promise.all([
        service.getSleepData(startDate, endDate),
        service.getWorkoutData(startDate, endDate),
      ])

      // Convert to sessions
      const healthSessions = SamsungHealthService.convertToSessions(
        sleepData,
        workoutData
      )

      // Notify parent component
      onSync(healthSessions)

      // Update last sync time
      const now = new Date()
      setLastSync(now)
      localStorage.setItem(`samsung_health_last_sync_${userId}`, now.toISOString())

      setSyncStatus('success')
    } catch (error) {
      console.error('Sync failed:', error)
      setSyncStatus('error')
    } finally {
      setIsSyncing(false)
      setTimeout(() => setSyncStatus('idle'), 3000)
    }
  }

  if (!isConnected) {
    return (
      <div className="bg-gradient-to-r from-blue-500/10 to-purple-500/10 border border-blue-500/30 rounded-lg p-6">
        <div className="flex items-start gap-4">
          <div className="p-3 bg-blue-500/20 rounded-lg">
            <Activity className="text-blue-400" size={24} />
          </div>
          
          <div className="flex-1">
            <h3 className="text-lg font-semibold text-white mb-1">
              Samsung Health Integration
            </h3>
            <p className="text-white/60 text-sm mb-4">
              Automatically import your sleep and workout data to see your full day timeline
            </p>

            <button
              onClick={handleConnect}
              className="flex items-center gap-2 bg-blue-500 hover:bg-blue-600 text-white font-medium px-4 py-2 rounded-lg transition-colors"
            >
              <Activity size={18} />
              Connect Samsung Health
            </button>

            <p className="text-xs text-white/40 mt-3">
              Note: Requires Samsung Health app and API setup
            </p>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="bg-black/40 border border-white/10 rounded-lg p-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-green-500/20 rounded-lg">
            <Activity className="text-green-400" size={20} />
          </div>
          
          <div>
            <div className="flex items-center gap-2">
              <span className="font-medium text-white">Samsung Health</span>
              <CheckCircle2 className="text-green-400" size={16} />
            </div>
            {lastSync && (
              <p className="text-xs text-white/60">
                Last synced: {lastSync.toLocaleString()}
              </p>
            )}
          </div>
        </div>

        <div className="flex items-center gap-2">
          {syncStatus === 'success' && (
            <span className="text-green-400 text-sm flex items-center gap-1">
              <CheckCircle2 size={16} />
              Synced!
            </span>
          )}
          {syncStatus === 'error' && (
            <span className="text-red-400 text-sm flex items-center gap-1">
              <AlertCircle size={16} />
              Error
            </span>
          )}

          <button
            onClick={handleSync}
            disabled={isSyncing}
            className="flex items-center gap-2 px-3 py-1.5 rounded-lg bg-white/10 hover:bg-white/20 text-white transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <RefreshCw size={16} className={isSyncing ? 'animate-spin' : ''} />
            {isSyncing ? 'Syncing...' : 'Sync Now'}
          </button>

          <button
            onClick={handleDisconnect}
            className="p-1.5 rounded-lg hover:bg-red-500/20 text-red-400 transition-colors"
            title="Disconnect"
          >
            <Unplug size={16} />
          </button>
        </div>
      </div>
    </div>
  )
}

